const n_AttachPicture = node({ type: "n8n-nodes-base.code", version: 2, config: { name: "Attach Picture", position: [2368, 1232], parameters: {"jsCode": "// Node: Attach Picture (Code) \u2014 puts the generated pictures on the reply and counts them against the account's\n// daily allowance. A chat answer gets one picture; a lesson gets one per section that asked for it, matched back by\n// the section index the picture step carried. If a picture failed, that part simply goes out without one.\n// v38 (A67): each picture is kept on the server for 90 days (ys_images, stored by the run log statement) and the\n// reply carries only a link with an unguessable id taken from the context query, so pictures come back after a\n// reload, a new sign-in or on another device. Without an id the picture goes out inline as before.\nvar frItems=$('Format Reply').all();\nvar fr=frItems[0].json;\nvar out={response:fr.response,logSql:fr.logSql,logParams:(Array.isArray(fr.logParams)?fr.logParams:[]).slice()};\nvar ids=[];\ntry{var cd=((($('Load Chat Context').first()||{}).json||{}).d)||{};ids=(Array.isArray(cd.imgIds)?cd.imgIds:[]).map(String).filter(function(x){return /^img-[0-9a-f]{32}$/.test(x);});}catch(e){ids=[];}\nfunction mimeOf(b){return b.slice(0,5)===\"UklGR\"?\"image/webp\":(b.slice(0,4)===\"/9j/\"?\"image/jpeg\":\"image/png\");}\nvar items=$input.all();\nvar made=0,firstErr=\"\",store=[];\nfor(var i=0;i<items.length;i++){\n var it=(items[i]||{}).json||{};\n var b64=\"\";\n try{b64=String((((it.data||[])[0])||{}).b64_json||\"\");}catch(e){b64=\"\";}\n // The section this picture belongs to travels with the item that asked for it.\n var src=(frItems[i]||{}).json||{};\n var secIdx=(src.sectionIndex==null)?null:Number(src.sectionIndex);\n if(!b64){\n  if(!firstErr)firstErr=it.error?String(it.error.message||it.error).slice(0,160):\"empty response\";\n  continue;\n }\n var mime=mimeOf(b64);\n var id=ids.length?ids.shift():\"\";\n var url=id?(\"/svc/img?id=\"+id):(\"data:\"+mime+\";base64,\"+b64);\n var kind=\"\";\n if(secIdx!=null&&out.response&&out.response.data&&out.response.data.lesson&&Array.isArray(out.response.data.lesson.sections)){\n  var sec=out.response.data.lesson.sections[secIdx];\n  if(sec&&typeof sec===\"object\"){sec.imageUrl=url;made++;kind=\"lesson\";}\n }else if(out.response&&out.response.message){\n  out.response.message.imageUrl=url;\n  out.response.message.imageAlt=\"Picture: \"+String(src.imagePrompt||fr.imagePrompt||\"illustration\").slice(0,120);\n  made++;kind=\"chat\";\n }\n if(kind&&id)store.push({id:id,kind:kind,mime:mime,b64:b64});\n}\nif(firstErr){if(!String(out.logParams[9]||\"\"))out.logParams[9]=\"image: \"+firstErr;}\nvar sql=String(fr.logSql||\"\");\nif(made>0){\n // Count them: a separate statement after the run log, so the ys_usage row already exists by then.\n sql+=\"; UPDATE ys_usage SET images=coalesce(images,0)+\"+made+\" WHERE owner_id=$2 AND day=current_date\";\n}\n// Keep each picture (ys_image_put never raises, so a picture that cannot be stored does not undo the run log).\nstore.forEach(function(s){var n=out.logParams.length;out.logParams.push(s.id,s.kind,s.mime,s.b64);sql+=\"; SELECT ys_image_put($\"+(n+1)+\",$2,$\"+(n+2)+\",$\"+(n+3)+\",$\"+(n+4)+\") AS stored\";});\nout.logSql=sql;\nreturn [{json:out}];\n"} } });
